mapper.select:
SELECT f.id, f.code, f.datetime_dep, f.datetime_arr, f.region_dep, f.region_arr, f.gate, f.distance, f.price, f.status FROM flight f
JOIN airport ad ON f.id_airport_dep = ad.id JOIN airport ar ON f.id_airport_arr = ar.id
AND f.region_dep = #{depCity}
AND f.region_arr = #{arrCity}
AND f.datetime_dep >= #{depDate} AND f.datetime_dep < DATE_ADD(#{depDate}, INTERVAL 1 DAY)
AND f.price >= #{priceMin}
AND f.price <= #{priceMax}
AND f.id_plane = #{planeId}
AND (ad.name = #{airportName} OR ar.name = #{airportName})
ORDER BY f.datetime_dep
